INSERT INTO instructors (id, slug, name, title, bio, is_ai_avatar, disclosure, sort_order, status, created_at, updated_at) VALUES ('ins_faculty', 'agro-ai-academy-faculty', 'AGRO-AI Academy Faculty', 'AGRO-AI agronomy, data science and product teams', 'Courses are written and reviewed by the AGRO-AI team, drawing on its work building irrigation, field and market intelligence for agricultural operations in the Americas.', 0, NULL, 0, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO instructors (id, slug, name, title, bio, is_ai_avatar, disclosure, sort_order, status, created_at, updated_at) VALUES ('ins_joshua', 'joshua', 'Joshua', 'AI presenter for AGRO-AI Academy video lessons', 'Joshua presents Academy video lessons. Lesson scripts are written and reviewed by the AGRO-AI Academy Faculty.', 1, 'Joshua is an AI-generated presenter (Synthesia). He is not a real person.', 1, 'hidden', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO courses (id, slug, program_id, title, subtitle, description, level, duration_minutes, source_locale, objectives_json, audience_json, topics_json, prerequisites_text, status, planned_release_date, certificate_enabled, passing_score, require_all_lessons, require_quizzes_pass, sort_order, content_review_note, created_at, updated_at) VALUES ('crs_a1', 'introduction-to-ai-in-agriculture', 'prg_a', 'Introduction to Artificial Intelligence in Agriculture', 'What AI is, how it works on the farm, and how to use it responsibly.', 'Artificial intelligence is arriving in agriculture through irrigation controllers, satellite services, farm management software and the phones in growers'' pockets. This course gives you a clear, practical understanding of what that technology is, how it works, and how to use it well.

You will learn the core ideas behind AI and machine learning without equations, see how agricultural data becomes a prediction and then a recommendation, and follow AI through the season — from planning and irrigation to crop health and harvest. Above all, you will learn to judge AI output: when to trust it, when to question it, and how to keep human judgment and farm knowledge in charge.

The course is designed for growers, operators, agronomists, managers and students. No technical background is required.', 'beginner', 150, 'en', '["Explain in plain language what artificial intelligence, machine learning and generative AI are","Describe the main sources of agricultural data and what makes data trustworthy","Follow how a model turns data into a prediction and a prediction into a recommendation","Recognize practical AI applications across the crop season, from planning to harvest","Identify the limits and failure modes of agricultural AI and when to challenge a recommendation","Apply principles of data ownership, privacy and responsible use on your own operation"]', '["grower","agronomist","farm_manager","operator","student","researcher","advisor"]', '["ai-foundations","data","precision-agriculture","ethics"]', 'None. Curiosity about how technology can support agricultural work is all you need.', 'review', '2026-10-29', 1, 80, 1, 0, 1, 'Faculty review of lesson text and exam bank before publication; record Joshua videos from the attached scripts once approved.', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO course_instructors (course_id, instructor_id, sort_order) VALUES ('crs_a1', 'ins_faculty', 0);
