INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m2_1', 'bnk_a1_m2', NULL, 'les_a1_data', 'single', 'easy', 'A rain gauge installed under a tree mostly harms which quality of data?', '{"options":[{"id":"o1","text":"Accuracy"},{"id":"o2","text":"Timeliness"},{"id":"o3","text":"Consistency of units"},{"id":"o4","text":"Portability"}]}', '{"correct":["o1"]}', 'The measurement no longer reflects actual rainfall, so its accuracy suffers.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m2_2', 'bnk_a1_m2', NULL, 'les_a1_models', 'single', 'medium', 'Why do data scientists keep some data aside during training?', '{"options":[{"id":"o1","text":"To test the model on examples it has never seen"},{"id":"o2","text":"To make training faster"},{"id":"o3","text":"To hide data from farmers"},{"id":"o4","text":"Because sensors produce too much data"}]}', '{"correct":["o1"]}', 'Held-out validation data gives an honest measure of how well a model works on new cases.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m2_3', 'bnk_a1_m2', NULL, 'les_a1_models', 'matching', 'medium', 'Match each model type with what it does.', '{"left":[{"id":"l1","text":"Regression"},{"id":"l2","text":"Classification"},{"id":"l3","text":"Forecasting"},{"id":"l4","text":"Optimization"}],"right":[{"id":"r5","text":"Predicts a number"},{"id":"r6","text":"Assigns a category"},{"id":"r7","text":"Predicts change over time"},{"id":"r8","text":"Finds the best plan within constraints"}]}', '{"pairs":{"l1":"r5","l2":"r6","l3":"r7","l4":"r8"}}', 'Each model family answers a different kind of question.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m2_4', 'bnk_a1_m2', NULL, 'les_a1_recommendations', 'true_false', 'easy', 'In agricultural decision support, the system proposes and a person decides.', '{}', '{"value":true}', 'Most agricultural AI is decision support; responsibility stays with people.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m2_5', 'bnk_a1_m2', NULL, 'les_a1_recommendations', 'multiple', 'medium', 'What should a good recommendation show you? Select all that apply.', '{"options":[{"id":"o1","text":"The reason behind it"},{"id":"o2","text":"How confident the system is"},{"id":"o3","text":"An evidence trail you can check later"},{"id":"o4","text":"Only a single number with no explanation"}]}', '{"correct":["o1","o2","o3"]}', 'Explanations, confidence and evidence make recommendations judgeable.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m2_6', 'bnk_a1_m2', NULL, 'les_a1_models', 'single', 'hard', 'A model that was accurate three years ago now performs poorly after a switch to new varieties. This is best described as…', '{"options":[{"id":"o1","text":"Drift"},{"id":"o2","text":"Overfitting to the validation set"},{"id":"o3","text":"Automation bias"},{"id":"o4","text":"Cloud masking"}]}', '{"correct":["o1"]}', 'Drift occurs when conditions change so past data no longer represents the present.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO question_banks (id, course_id, title, description, created_at, updated_at) VALUES ('bnk_a1_m3', 'crs_a1', 'A1 · Module 3 practice', '', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m3_1', 'bnk_a1_m3', NULL, 'les_a1_crop_health', 'single', 'easy', 'Healthy green vegetation strongly reflects which kind of light?', '{"options":[{"id":"o1","text":"Near-infrared"},{"id":"o2","text":"Red"},{"id":"o3","text":"Ultraviolet"},{"id":"o4","text":"Blue"}]}', '{"correct":["o1"]}', 'Healthy leaves reflect near-infrared strongly and absorb red light.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m3_2', 'bnk_a1_m3', NULL, 'les_a1_crop_health', 'short_answer', 'medium', 'What is the common four-letter abbreviation for the Normalized Difference Vegetation Index?', '{"max_length":120}', '{"accepted":["NDVI"],"match":"exact"}', 'NDVI = (NIR − Red) ÷ (NIR + Red).', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m3_3', 'bnk_a1_m3', NULL, 'les_a1_irrigation', 'single', 'medium', 'Crop water use (ETc) is commonly estimated as…', '{"options":[{"id":"o1","text":"Reference evapotranspiration × crop coefficient"},{"id":"o2","text":"Rainfall − irrigation"},{"id":"o3","text":"Soil moisture × yield"},{"id":"o4","text":"NDVI × temperature"}]}', '{"correct":["o1"]}', 'ETc = ET₀ × Kc.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m3_4', 'bnk_a1_m3', NULL, 'les_a1_crop_health', 'true_false', 'easy', 'A low-NDVI patch tells you exactly what is wrong with the crop.', '{}', '{"value":false}', 'NDVI shows where a field differs; scouting determines why.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m3_5', 'bnk_a1_m3', NULL, 'les_a1_planning', 'single', 'medium', 'Grouping areas of a field that respond similarly to water and inputs creates…', '{"options":[{"id":"o1","text":"Management zones"},{"id":"o2","text":"Validation sets"},{"id":"o3","text":"Crop coefficients"},{"id":"o4","text":"Market signals"}]}', '{"correct":["o1"]}', 'Management zones allow site-specific decisions.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1m3_6', 'bnk_a1_m3', NULL, 'les_a1_irrigation', 'single', 'hard', 'A root zone holds 16 mm of readily available water and the crop uses 4 mm per day with no rain. About how many days until it reaches its lower limit?', '{"options":[{"id":"o1","text":"4 days"},{"id":"o2","text":"2 days"},{"id":"o3","text":"8 days"},{"id":"o4","text":"16 days"}]}', '{"correct":["o1"]}', '16 mm ÷ 4 mm/day = 4 days.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO question_banks (id, course_id, title, description, created_at, updated_at) VALUES ('bnk_a1_exam', 'crs_a1', 'A1 · Certification exam bank', '', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO question_cases (id, bank_id, title, body_md, created_at) VALUES ('cas_a1_orchard', 'bnk_a1_exam', 'Case: an orchard irrigation recommendation', 'A citrus grower receives this recommendation: *“Irrigate Block 2 for 8 hours tonight. Predicted water use: 6 mm/day. Confidence: medium.”* The soil moisture probe in Block 2 has not reported for three days, and the system is using its last known reading. A heat wave is forecast for the next four days.', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e1', 'bnk_a1_exam', NULL, 'les_a1_what_is_ai', 'single', 'easy', 'Most of what people call “AI” today is…', '{"options":[{"id":"o1","text":"Machine learning"},{"id":"o2","text":"Hand-written rules"},{"id":"o3","text":"Mechanical automation"},{"id":"o4","text":"Satellite photography"}]}', '{"correct":["o1"]}', 'Machine learning is the dominant approach behind modern AI.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e2', 'bnk_a1_exam', NULL, 'les_a1_what_is_ai', 'true_false', 'easy', 'AI can carry legal and practical responsibility for a farm decision.', '{}', '{"value":false}', 'Responsibility for decisions stays with people.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e3', 'bnk_a1_exam', NULL, 'les_a1_data', 'single', 'easy', 'A moisture sensor stops reporting for a week during a heat wave. Which data quality is most affected?', '{"options":[{"id":"o1","text":"Completeness"},{"id":"o2","text":"Consistency of units"},{"id":"o3","text":"Representativeness of soil types"},{"id":"o4","text":"Ownership"}]}', '{"correct":["o1"]}', 'The data has a gap exactly when it matters most.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e4', 'bnk_a1_exam', NULL, 'les_a1_crop_health', 'single', 'easy', 'On an NDVI map, which surface usually has the lowest values?', '{"options":[{"id":"o1","text":"Open water"},{"id":"o2","text":"Dense healthy canopy"},{"id":"o3","text":"Young crop"},{"id":"o4","text":"Orchard rows"}]}', '{"correct":["o1"]}', 'Water typically has negative NDVI values.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e5', 'bnk_a1_exam', NULL, 'les_a1_recommendations', 'true_false', 'easy', 'Verifying whether an irrigation actually ran and had the expected effect helps catch equipment problems.', '{}', '{"value":true}', 'Verification closes the loop and builds trust.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e6', 'bnk_a1_exam', NULL, 'les_a1_data_rights', 'single', 'easy', 'When connecting a device that only needs to read irrigation data, you should grant…', '{"options":[{"id":"o1","text":"The least access needed, such as read-only"},{"id":"o2","text":"Full control of every setting"},{"id":"o3","text":"Access to all of your farm records"},{"id":"o4","text":"Permanent access that cannot be revoked"}]}', '{"correct":["o1"]}', 'Least-privilege access limits risk.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e7', 'bnk_a1_exam', NULL, 'les_a1_why_now', 'single', 'easy', 'According to the FAO, roughly what share of global freshwater withdrawals is used by agriculture?', '{"options":[{"id":"o1","text":"About 70%"},{"id":"o2","text":"About 10%"},{"id":"o3","text":"About 30%"},{"id":"o4","text":"Almost 100%"}]}', '{"correct":["o1"]}', 'Agriculture accounts for roughly 70% of global freshwater withdrawals.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e8', 'bnk_a1_exam', NULL, 'les_a1_data', 'multiple', 'easy', 'Which of these are sources of agricultural data? Select all that apply.', '{"options":[{"id":"o1","text":"Weather stations"},{"id":"o2","text":"Satellite imagery"},{"id":"o3","text":"Irrigation flow meters"},{"id":"o4","text":"Your own scouting notes"}]}', '{"correct":["o1","o2","o3","o4"]}', 'All of these are valuable sources of farm data.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_e9', 'bnk_a1_exam', NULL, 'les_a1_irrigation', 'short_answer', 'easy', 'Crop water use plus soil evaporation is called evapo______ (complete the word).', '{"max_length":120}', '{"accepted":["transpiration","evapotranspiration"],"match":"exact"}', 'Evapotranspiration (ET) combines plant transpiration and soil evaporation.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m1', 'bnk_a1_exam', NULL, 'les_a1_models', 'single', 'medium', 'A vendor says their model “fits our historical data perfectly.” What is the best response?', '{"options":[{"id":"o1","text":"Ask how it performs on data it never saw during training"},{"id":"o2","text":"Adopt it immediately"},{"id":"o3","text":"Assume it will be perfect on your farm"},{"id":"o4","text":"Ignore validation because the fit is perfect"}]}', '{"correct":["o1"]}', 'A perfect historical fit can signal memorization; held-out validation is the honest test.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m2', 'bnk_a1_exam', NULL, 'les_a1_data', 'matching', 'medium', 'Match each data problem with the quality it violates.', '{"left":[{"id":"l1","text":"Inches mixed with millimeters"},{"id":"l2","text":"Probe placed in an unusually wet spot"},{"id":"l3","text":"Last month''s soil moisture used for today''s decision"},{"id":"l4","text":"Model trained only on sandy soils, used on clay"}],"right":[{"id":"r5","text":"Consistency"},{"id":"r6","text":"Accuracy"},{"id":"r7","text":"Timeliness"},{"id":"r8","text":"Representativeness"}]}', '{"pairs":{"l1":"r5","l2":"r6","l3":"r7","l4":"r8"}}', 'Each issue undermines a different dimension of data quality.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m3', 'bnk_a1_exam', NULL, 'les_a1_limits', 'multiple', 'medium', 'Which situations should prompt you to investigate before acting on a recommendation? Select all that apply.', '{"options":[{"id":"o1","text":"It contradicts what you see in the field"},{"id":"o2","text":"Key input data is stale"},{"id":"o3","text":"The decision is costly and hard to reverse"},{"id":"o4","text":"It matches field observations and the data is current"}]}', '{"correct":["o1","o2","o3"]}', 'Conflicts, poor data and high stakes all warrant a second look.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m4', 'bnk_a1_exam', NULL, 'les_a1_crop_health', 'single', 'medium', 'Why do reliable satellite services compare images over time instead of using a single snapshot?', '{"options":[{"id":"o1","text":"Clouds, shadows and haze can distort individual images"},{"id":"o2","text":"Satellites only work at night"},{"id":"o3","text":"NDVI never changes during a season"},{"id":"o4","text":"Single images are illegal to use"}]}', '{"correct":["o1"]}', 'Comparing over time and masking clouds reduces false alarms.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m5', 'bnk_a1_exam', NULL, 'les_a1_limits', 'ordering', 'medium', 'Order these steps for challenging a recommendation well.', '{"items":[{"id":"o1","text":"Check the inputs"},{"id":"o2","text":"Ask for the reason"},{"id":"o3","text":"Look in the field"},{"id":"o4","text":"Record what you decided and why"}]}', '{"order":["o1","o2","o3","o4"]}', 'Check inputs, understand the reason, verify in the field, then record your decision as feedback.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m6', 'bnk_a1_exam', NULL, 'les_a1_recommendations', 'single', 'medium', 'Which element turns a water-use prediction into an irrigation recommendation?', '{"options":[{"id":"o1","text":"Combining it with goals, constraints and context"},{"id":"o2","text":"Rounding it to whole millimeters"},{"id":"o3","text":"Displaying it on a map"},{"id":"o4","text":"Sending it by email"}]}', '{"correct":["o1"]}', 'Recommendations weigh predictions against goals, constraints and context.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m7', 'bnk_a1_exam', NULL, 'les_a1_what_is_ai', 'single', 'medium', 'What is the main risk of using a generative AI assistant to answer “How much nitrogen should I apply to field 12?”', '{"options":[{"id":"o1","text":"It may give a plausible but unverified answer"},{"id":"o2","text":"It cannot write in full sentences"},{"id":"o3","text":"It only works with images"},{"id":"o4","text":"It always refuses agricultural questions"}]}', '{"correct":["o1"]}', 'Generative AI predicts plausible text; important numbers must be checked against trusted data and expertise.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m8', 'bnk_a1_exam', NULL, 'les_a1_models', 'true_false', 'medium', 'A forecast of “6.2 mm, likely between 5.6 and 6.8 mm” is more informative than “6.2 mm” alone.', '{}', '{"value":true}', 'Communicating uncertainty helps you judge how much to rely on a prediction.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m9', 'bnk_a1_exam', NULL, 'les_a1_harvest', 'single', 'medium', 'How should a market price forecast generated by AI be used?', '{"options":[{"id":"o1","text":"As one input to a risk-managed marketing plan"},{"id":"o2","text":"As a guaranteed price"},{"id":"o3","text":"Only after harvest is complete"},{"id":"o4","text":"Never, because markets cannot be analyzed"}]}', '{"correct":["o1"]}', 'Market forecasts are uncertain and belong inside a broader risk plan.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m10', 'bnk_a1_exam', NULL, 'les_a1_data_rights', 'multiple', 'medium', 'Which questions should you ask a provider before sharing farm data? Select all that apply.', '{"options":[{"id":"o1","text":"Can I download my data and take it with me?"},{"id":"o2","text":"Will my data be used to train models?"},{"id":"o3","text":"Can I delete my data?"},{"id":"o4","text":"What color is the company logo?"}]}', '{"correct":["o1","o2","o3"]}', 'Portability, use and deletion are central to data rights.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m11', 'bnk_a1_exam', NULL, 'les_a1_planning', 'single', 'medium', 'Why are local trial results usually more relevant than national averages for variety selection?', '{"options":[{"id":"o1","text":"They reflect your soils and climate"},{"id":"o2","text":"They are always larger datasets"},{"id":"o3","text":"They never contain errors"},{"id":"o4","text":"National averages are not allowed in models"}]}', '{"correct":["o1"]}', 'Representative data gives more relevant recommendations.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m12', 'bnk_a1_exam', 'cas_a1_orchard', 'les_a1_limits', 'single', 'medium', 'In the orchard case, what is the most important weakness in the recommendation''s inputs?', '{"options":[{"id":"o1","text":"The soil moisture probe has not reported for three days"},{"id":"o2","text":"The recommendation is for nighttime irrigation"},{"id":"o3","text":"The block is named Block 2"},{"id":"o4","text":"Citrus does not need irrigation"}]}', '{"correct":["o1"]}', 'A stale sensor reading means the system may not know the current soil moisture.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m13', 'bnk_a1_exam', 'cas_a1_orchard', 'les_a1_limits', 'multiple', 'medium', 'In the orchard case, which actions are sensible? Select all that apply.', '{"options":[{"id":"o1","text":"Inspect the probe and restore its data feed"},{"id":"o2","text":"Check soil moisture in Block 2 by hand"},{"id":"o3","text":"Consider the forecast heat wave when deciding how much to irrigate"},{"id":"o4","text":"Disable all recommendations permanently"}]}', '{"correct":["o1","o2","o3"]}', 'Fix the data, verify in the field, and account for the forecast.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_m14', 'bnk_a1_exam', NULL, 'les_a1_irrigation', 'single', 'medium', 'Which statement about the crop coefficient (Kc) is correct?', '{"options":[{"id":"o1","text":"It adjusts reference ET for the crop and its growth stage"},{"id":"o2","text":"It measures rainfall"},{"id":"o3","text":"It is the same for every crop and stage"},{"id":"o4","text":"It replaces weather data"}]}', '{"correct":["o1"]}', 'Kc varies by crop and stage: ETc = ET₀ × Kc.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_h1', 'bnk_a1_exam', NULL, 'les_a1_irrigation', 'single', 'hard', 'A root zone holds 30 mm of readily available water when full. A probe shows 12 mm remaining, forecast ETc is 4 mm/day, and 8 mm of effective rain is expected on day 2. Without irrigation, roughly when will the lower limit be reached?', '{"options":[{"id":"o1","text":"About day 5"},{"id":"o2","text":"About day 3"},{"id":"o3","text":"About day 1"},{"id":"o4","text":"It will never be reached"}]}', '{"correct":["o1"]}', '12 mm − 4 (day 1) = 8; −4 + 8 (day 2) = 12; then 4 mm/day lasts about 3 more days, reaching the limit around day 5.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_h2', 'bnk_a1_exam', NULL, 'les_a1_crop_health', 'single', 'hard', 'A pixel has near-infrared reflectance of 0.50 and red reflectance of 0.10. What is its NDVI?', '{"options":[{"id":"o1","text":"About 0.67"},{"id":"o2","text":"About 0.40"},{"id":"o3","text":"About 0.20"},{"id":"o4","text":"About 5.0"}]}', '{"correct":["o1"]}', '(0.50 − 0.10) ÷ (0.50 + 0.10) = 0.40 ÷ 0.60 ≈ 0.67.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_h3', 'bnk_a1_exam', NULL, 'les_a1_limits', 'multiple', 'hard', 'A disease-detection app trained mostly on images from one country performs poorly on your farm. Which explanations are plausible? Select all that apply.', '{"options":[{"id":"o1","text":"Training data was not representative of your varieties"},{"id":"o2","text":"Lighting and camera conditions differ"},{"id":"o3","text":"The app is affected by bias in its training data"},{"id":"o4","text":"The app works perfectly; your crop must be healthy"}]}', '{"correct":["o1","o2","o3"]}', 'Representativeness and bias limit how well models transfer to new conditions.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_h4', 'bnk_a1_exam', NULL, 'les_a1_limits', 'single', 'hard', 'Staff accept every system recommendation because the numbers look precise. This tendency is called…', '{"options":[{"id":"o1","text":"Automation bias"},{"id":"o2","text":"Data drift"},{"id":"o3","text":"Cloud masking"},{"id":"o4","text":"Supervised learning"}]}', '{"correct":["o1"]}', 'Automation bias is the tendency to over-trust machine output.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_h5', 'bnk_a1_exam', NULL, 'les_a1_why_now', 'matching', 'hard', 'Match each step of the decision loop with an example.', '{"left":[{"id":"l1","text":"Sense"},{"id":"l2","text":"Predict"},{"id":"l3","text":"Recommend"},{"id":"l4","text":"Verify"}],"right":[{"id":"r5","text":"Satellite imagery reveals a stressed zone"},{"id":"r6","text":"A model estimates tomorrow''s water use"},{"id":"r7","text":"Irrigate block 4 tonight for 6 hours"},{"id":"r8","text":"Flow meters confirm 18 mm was applied"}]}', '{"pairs":{"l1":"r5","l2":"r6","l3":"r7","l4":"r8"}}', 'Each step of sense → predict → recommend → verify has a distinct role.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_h6', 'bnk_a1_exam', 'cas_a1_orchard', 'les_a1_limits', 'true_false', 'hard', 'In the orchard case, the “medium” confidence label means the grower can safely skip any field check.', '{}', '{"value":false}', 'Medium confidence combined with a stale sensor is a reason to check, not to skip verification.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
INSERT INTO questions (id, bank_id, case_id, lesson_id, type, difficulty, prompt, data_json, answer_json, explanation, grading, points, status, created_at, updated_at) VALUES ('q_a1x_h7', 'bnk_a1_exam', NULL, 'les_a1_data_rights', 'single', 'hard', 'Pooling data from many farms can improve regional models. What makes this acceptable from a data-rights perspective?', '{"options":[{"id":"o1","text":"Proper anonymization and clear consent, including an opt-out"},{"id":"o2","text":"Selling the combined dataset to the highest bidder"},{"id":"o3","text":"Hiding the practice from farmers"},{"id":"o4","text":"Using it only if a competitor asks"}]}', '{"correct":["o1"]}', 'Aggregation should protect identities and respect farmers'' choices.', 'auto', 1, 'active', '2026-10-17T00:00:00.000Z', '2026-10-17T00:00:00.000Z');
